def max_product(num_str: str, N: int, K: int) -> int:
    if not num_str or N != len(num_str) or K < 0 or K >= N - 1:
        raise ValueError("Invalid input parameters")

    num_list = list(num_str)
    for _ in range(K):
        max_pair = (0, 0)
        max_product = 0
        for i in range(len(num_list) - 1):
            product = int(num_list[i]) * int(num_list[i + 1])
            if product > max_product:
                max_product = product
                max_pair = (i, i + 1)
        num_list.insert(max_pair[1], '*')

    result = 1
    for char in num_list:
        if char != '*':
            result *= int(char)

    return result
