def max_energy(beads):
    n = len(beads)
    if n < 3:
        return 0

    # Create a 2D DP table
    dp = [[0] * n for _ in range(n)]

    # Initialize the DP table with single bead segments
    for i in range(n):
        dp[i][i] = 0

    # Fill the DP table
    for length in range(2, n):
        for i in range(n):
            j = (i + length) % n
            for k in range(i, j):
                dp[i][j] = max(dp[i][j], dp[i][k] + dp[k + 1][j] + beads[i] * beads[k + 1] // beads[k] * beads[j])

    return dp[0][n - 1]
