def count_coprime_pairs(x0: int, y0: int) -> int:
    if x0 <= 0 or y0 <= 0:
        return 0
    if x0 == y0:
        return 1
    quotient = y0 // x0
    if y0 % x0 != 0:
        return 0
    count = 0
    for a in range(1, quotient + 1):
        if quotient % a == 0:
            b = quotient // a
            if gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2
    return count

