def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    # Filter out statements about the day of the week
    relevant_statements = {participant: [stmt for stmt in stmts if stmt not in days_of_week] for participant, stmts in statements.items()}

    # Check consistency
    for participant, stmts in relevant_statements.items():
        for stmt in stmts:
            # If the participant is in the liar set, they should make false statements
            if participant in liar_count:
                if stmt.startswith("I am guilty.") and participant == scenario:
                    return False
                if stmt.startswith(f"{scenario} is not guilty.") and participant != scenario:
                    return False
            else:
                # If the participant is not in the liar set, they should make true statements
                if stmt.startswith("I am guilty.") and participant != scenario:
                    return False
                if stmt.startswith(f"{scenario} is not guilty.") and participant == scenario:
                    return False

    return True
