def calculate_score(system: int, points: str) -> list:
    if system not in [11, 21]:
        raise ValueError("Invalid system. Must be either 11 or 21.")

    if not points:
        return []

    scores = []
    player_score = 0
    opponent_score = 0

    for point in points:
        if point == 'W':
            player_score += 1
        elif point == 'L':
            opponent_score += 1
        else:
            raise ValueError("Invalid points string. Must contain only 'W' and 'L'.")

        if max(player_score, opponent_score) >= system and abs(player_score - opponent_score) >= 2:
            scores.append(f"{player_score}:{opponent_score}")
            player_score = 0
            opponent_score = 0

    if player_score != 0 or opponent_score != 0:
        scores.append(f"{player_score}:{opponent_score}")

    return scores
