def minimum_students_to_leave(heights):
    n = len(heights)
    if n == 0:
        return 0

    # Initialize the left and right lists
    left = [1] * n
    right = [1] * n

    # Calculate the longest increasing subsequence ending at each position
    for i in range(1, n):
        for j in range(i):
            if heights[i] > heights[j]:
                left[i] = max(left[i], left[j] + 1)

    # Calculate the longest decreasing subsequence starting at each position
    for i in range(n-2, -1, -1):
        for j in range(i+1, n):
            if heights[i] > heights[j]:
                right[i] = max(right[i], right[j] + 1)

    # Find the maximum length of the choired formation
    max_choir_length = 0
    for i in range(n):
        max_choir_length = max(max_choir_length, left[i] + right[i] - 1)

    # The minimum number of students to leave is the total number of students minus the maximum choir length
    return n - max_choir_length
